head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.pwcnt = 0;
scwin.contnId;
scwin.loadset = 0;
scwin.rowPosition = 0;
scwin.gRegEmpNo;
scwin.vScrenID = "ULDSTF30301.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetCode = function() {
    /*	
    		// 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    		//if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    		if (js_dep_cd.substring(0,1) == '2'  || js_dep_cd.substring(0,2) == '34' ) {
    			showObj(panel_2, true);				
    		} else{
    			showObj(panel_2, false);
    		}
    */

    //  지식구분 셋팅
    dts_KnowlgTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=LD_KNOWLG_TP_CD";
    dts_KnowlgTp.Reset();

    //  보안수준구분 셋팅
    dts_SecuLvlTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=KNOWLG_SECU_LVL_TP_CD";
    dts_SecuLvlTp.Reset();
};
scwin.fn_read = function() {
    trs_Read.Action = "/ShareRoom.do?method=readShareRoom&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_ShareRoomInfo,O:pOutput2=dts_fileList)";
    trs_Read.Post();
    /*		
    		// 카운트 증가
    		trs_count.Action="/ShareRoom.do?method=addCountShareRoom&CONTN_ID="+contnId;
    		trs_count.KeyValue="JSP(I:pInput1=dts_ShareRoomInfo)";
    		trs_count.Post();		
    */

};
scwin.fn_save = function() {
    if (dts_fileList.getCellData(1, "fileInfo") == "") {
        dts_fileList.Reset();
    }
    if ($c.stf.getObjectValue(cmb_knowlg_tp).length < 1) {
        $c.win.alert("지식구분을 선택하시오.");
        cmb_knowlg_tp.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_secu_lvl_tp).length < 1) {
        $c.win.alert("보안수준을 선택하시오.");
        cmb_secu_lvl_tp.focus();
        return;
    }
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    if (scwin.getChkValue(cbox_mail_yn) == "1" && scwin.checkFileSize() == false) {
        $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    var rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        tbox_wrtr_emp_nm.setValue(js_emp_no);
        dts_ShareRoomInfo.setCellData(1, "REG_DEP_CD", js_dep_cd);
        dts_ShareRoomInfo.setCellData(1, "IMPT_CONTN_YN", scwin.getChkValue(chb_impt_contn_yn));
        dts_ShareRoomInfo.setCellData(1, "MAIL_SEND_YN", scwin.getChkValue(cbox_mail_yn));
        dts_ShareRoomInfo.setCellData(1, "WRTR_EMP_EMAIL", js_inside_email);
        trs_Save.Action = "/ShareRoom.do?method=registerShareRoom" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_ShareRoomInfo,I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_delete = function() {
    if (js_emp_no != scwin.gRegEmpNo) {
        $c.win.alert("게시물 등록자만 삭제처리 할 수 있습니다.");
        return false;
    }
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_ShareRoomDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ShareRoomDel.insertRow();
        dts_ShareRoomDel.setCellData(1, "CONTN_ID", scwin.contnId);
        trs_Delete.Action = "/ShareRoom.do?method=removeShareRoom" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_ShareRoomDel)";
        trs_Delete.Post();
    }
};
scwin.fn_update = function() {
    /*
    		if ( js_emp_no !=  gRegEmpNo) {
    			alert("게시물 등록자만  수정처리 할 수 있습니다.");
    			return false ;
    		}
    */

    if ($c.stf.getObjectValue(cmb_knowlg_tp).length < 1) {
        $c.win.alert("지식구분을 선택하시오.");
        cmb_knowlg_tp.focus();
        return;
    }
    if ($c.stf.getObjectValue(cmb_secu_lvl_tp).length < 1) {
        $c.win.alert("보안수준을 선택하시오.");
        cmb_secu_lvl_tp.focus();
        return;
    }
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(tbox_title, 100, "제목")) {
        tbox_title.setValue("");
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.text = "";
        tarea_contn_contn.focus();
        return false;
    }
    if (scwin.getChkValue(cbox_mail_yn) == "1" && scwin.checkFileSize() == false) {
        $c.win.alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        return false;
    }
    var rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_ShareRoomInfo.setCellData(1, "REG_DEP_CD", js_dep_cd);
        dts_ShareRoomInfo.setCellData(1, "IMPT_CONTN_YN", scwin.getChkValue(chb_impt_contn_yn));
        dts_ShareRoomInfo.setCellData(1, "MAIL_SEND_YN", scwin.getChkValue(cbox_mail_yn));
        dts_ShareRoomInfo.setCellData(1, "WRTR_EMP_EMAIL", js_inside_email);
        trs_Update.Action = "/ShareRoom.do?method=modifyShareRoom&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Update.KeyValue = "JSP(I:pInput1=dts_ShareRoomInfo,I:pInput2=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_setDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_SetSaveHeader = function() {
    // CUD용 Header
    dts_ShareRoomInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_SHARE_ROOM_READ_INOUT";
    dts_ShareRoomInfo.Reset();
    dts_ShareRoomInfo.insertRow();
};

//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?file_id=" + scwin.contnId + "&attach_seq=" + attach_seq + "&gubun=2";
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.iniAttachFilePw = function() {
    filePw.setValue("");
    for (var z = 1; z < 6; z++) {
        dts_fileList.setCellData(z, "ATTACH_FILE_PW", "");
    }
};
scwin.iniPicYn = function() {
    for (var z = 1; z < 6; z++) {
        dts_fileList.setCellData(z, "PIC_YN", "F");
    }
};
scwin.iniPicYnSet = function() {
    for (var z = 1; z < 6; z++) {
        if (dts_fileList.getCellData(z, "ATTACH_FILE_PW") != "") {
            dts_fileList.setCellData(z, "PIC_YN", "T");
            scwin.pwcnt = 1;
        } else {
            dts_fileList.setCellData(z, "PIC_YN", "F");
        }
    }
};
scwin.iniAtachfFilePwSet = function() {
    var vcnt = 0;
    for (var z = 1; z < 6; z++) {
        if (dts_fileList.getCellData(z, "ATTACH_FILE_PW") != "") {
            dts_fileList.setCellData(z, "PIC_YN", "T");
            scwin.pwcnt = 1;
            vcnt += 1;
            if (vcnt > 0) {
                $c.stf.showObj(filePw, true);
                $c.stf.showObj(label_16, true);
                $c.stf.showObj(btn_input, true);
                filePw.setValue(dts_fileList.getCellData(z, "ATTACH_FILE_PW"));
            }
        } else {
            dts_fileList.setCellData(z, "PIC_YN", "F");
        }
    }
};
scwin.copyAttachFilePw = function() {
    var vcnt = 0;
    for (var z = 1; z < 6; z++) {
        if (dts_fileList.getCellData(z, "PIC_YN") == "T") {
            dts_fileList.setCellData(z, "ATTACH_FILE_PW", filePw.getValue());
            scwin.pwcnt = 1;
            vcnt += 1;
        } else {
            dts_fileList.setCellData(z, "ATTACH_FILE_PW", "");
        }
    }
    if (vcnt < 1) {
        scwin.iniAttachFilePw();
        scwin.pwcnt = 0;
    }
};
scwin.chHolding = function() {
    if (dts_fileList.getCellData(dts_fileList.getRowPosition(), "PIC_YN") == "T") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "PIC_YN", "F");
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "PIC_YN", "T");
    }
};
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};



/**
 * 전체 파일 사이즈 체크
 */
scwin.checkFileSize = function() {
    var maxFileSize = 1024 * 30; //30MB		
    var totalFileSize = 0;
    var isValid = true;
    for (var i = 1; i <= dts_fileList.getTotalRow(); i++) {
        totalFileSize = Number(totalFileSize) + Number(dts_fileList.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > maxFileSize) {
        //alert("전체 파일용량은 30MB를 초과할 수 없습니다");
        isValid = false;
    }
    return isValid;
};
scwin.btn_save_onclick = function() {
    if (scwin.contnId == "input") {
        scwin.fn_save();
    } else {
        scwin.fn_update();
    }
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "보고및 공유자료등록"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "보고및 공유자료등록"));
    $c.win.alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "보고및 공유자료수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "보고및 공유자료수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "보고및 공유자료삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "보고및 공유자료삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.trs_count_OnSuccess = function() {
    $c.win.alert('trs_count.OnSuccess()');
};
scwin.trs_count_OnFail = function() {
    $c.win.alert(trs_count.ErrorMsg);
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
    if (scwin.contnId == "input") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileList.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    var posV = Math.pow(10, 1);
    if (inf_find.getValue() != "") {
        if (scwin.contnId == "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
            var fileSize = inf_find.FileInfo('size');
            fileSize = Math.round(fileSize / 1024 * posV) / posV;
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_SIZE", fileSize);
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.getValue());
            var fileSize = inf_find.FileInfo('size');
            fileSize = Math.round(fileSize / 1024 * posV) / posV;
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "FILE_SIZE", fileSize);
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
    if (!scwin.canUploadFile()) {
        $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        return;
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.grd_fileList_onkeydown = function() {
    if (event.keyCode == 13 || event.keyCode == 32) {
        scwin.chHolding();
        return;
    }

};
scwin.grd_fileList_OnClick = function(row, colid) {
    if (colid == "filename") {
        if (scwin.contnId != "input") {
            dts_fileList.setRowPosition(0, 0);
        }
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
            if (dts_fileList.getCellData(row, "ATTACH_FILE_PW") != "" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") != js_emp_no) {
                if (dts_fileList.getCellData(row, "ATTACH_FILE_PW") == filePw.getValue()) {
                    dts_fileList.setCellData(row, "PIC_YN", "T");
                    scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
                } else {
                    $c.stf.showObj(filePw, true);
                    $c.stf.showObj(label_16, true);
                    $c.stf.showObj(btn_input, true);
                    scwin.setFocusedCell(row, 0);
                    if (filePw.getValue() != "") {
                        $c.win.alert("비밀번호가 올바르지 않습니다.");
                    } else {
                        $c.win.alert("비밀번호를 입력해주세요");
                    }
                    filePw.focus();
                }
            } else {
                if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") == js_emp_no) {
                    scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
                } else {
                    filePw.setValue("");
                    $c.stf.showObj(filePw, false);
                    $c.stf.showObj(label_16, false);
                    $c.stf.showObj(btn_input, false);
                    scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
                }
            }
        }
    } else {
        if (scwin.contnId == "input" || dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") == js_emp_no) {
            scwin.copyAttachFilePw();
            if (scwin.pwcnt > 0) {
                if ($c.stf.getObjectValue(rdo_creatloc_tp) == "01") {
                    $c.stf.showObj(filePw, true);
                    $c.stf.showObj(label_16, true);
                    $c.stf.showObj(btn_input, true);
                } else {
                    $c.stf.showObj(filePw, false);
                    $c.stf.showObj(label_16, false);
                    $c.stf.showObj(btn_input, false);
                    scwin.iniAttachFilePw();
                }
            } else {
                $c.stf.showObj(filePw, false);
                $c.stf.showObj(label_16, false);
                $c.stf.showObj(btn_input, false);
                scwin.iniAttachFilePw();
            }
        } else {
            filePw.setValue("");
        }
    }
    return true;
};
scwin.img_keyword_srch_onclick = async function() {
    var url = "/bizspt/ULDSTF30324.gfm";
    var winTitle = "주요키워드 선택 ";
    await $c.frame.CreateDialogFrame("KEYWORD", url, winTitle, 100, 10, 790, 570, "window");
};
scwin.dts_ShareRoomInfo_OnLoadError = function() {
    $c.win.alert('dts_ShareRoomInfo.OnLoadError()');
};
scwin.dts_ShareRoomInfo_OnLoadCompleted = function(rowcount) {
    scwin.gRegEmpNo = dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO");
    if (dts_ShareRoomInfo.getCellData(0, "IMPT_CONTN_YN") == 'Y') {
        if (scwin.pwcnt > 0) {
            scwin.setChkValue(chb_impt_contn_yn, true);
        } else {
            scwin.setChkValue(chb_impt_contn_yn, false);
        }
    } else {
        scwin.setChkValue(chb_impt_contn_yn, false);
    }
};
scwin.dts_SecuLvlTp_OnLoadCompleted = function(rowcount) {
    if (scwin.contnId == "input") {
        $c.stf.setObjectValue(cmb_secu_lvl_tp, '04');
    }
};
scwin.rdo_creatloc_tp_OnSelChange = function() {
    //alert(getObjectValue(rdo_creatloc_tp));
    dts_KnowlgTp.UseFilter = true;
    dts_KnowlgTp.Filter();
    cmb_knowlg_tp.trigger("onclick");
    if (scwin.contnId != "input") {
        filePw.setValue("");
        scwin.iniPicYn();
        $c.stf.showObj(filePw, false);
        $c.stf.showObj(label_16, false);
        $c.stf.showObj(btn_input, false);
        if ($c.stf.getObjectValue(rdo_creatloc_tp) != "01" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") == js_emp_no) {
            scwin.iniAttachFilePw();
        }
    } else {
        if ($c.stf.getObjectValue(rdo_creatloc_tp) == "01") {
            if (scwin.pwcnt > 0) {
                $c.stf.showObj(filePw, true);
                $c.stf.showObj(label_16, true);
                $c.stf.showObj(btn_input, true);
            }
        } else {
            $c.stf.showObj(filePw, false);
            $c.stf.showObj(label_16, false);
            $c.stf.showObj(btn_input, false);
            scwin.iniAttachFilePw();
        }
    }
};
scwin.dts_KnowlgTp_OnFilter = function(row) {
    //  생성처에 따른 지식구분을 가져온다.
    if ($c.stf.getObjectValue(rdo_creatloc_tp) == '01') {
        if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) == 'A' ||
            dts_KnowlgTp.getCellData(row, "value") == '') {
            return true;
        } else {
            return false;
        }
    } else if ($c.stf.getObjectValue(rdo_creatloc_tp) == '02') {
        if (dts_KnowlgTp.getCellData(row, "value").substr(0, 1) == 'B' ||
            dts_KnowlgTp.getCellData(row, "value") == '') {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
};
scwin.img_update_onclick = function() {
    scwin.fn_update();
};
scwin.filePw_onkeyup = function() {
    if (scwin.contnId != "input" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") != js_emp_no) {

    } else {
        scwin.copyAttachFilePw();
    }
};
scwin.btn_input_onclick = function() {
    if (dts_fileList.getCellData(scwin.rowPosition, "ATTACH_FILE_PW") == filePw.getValue()) {
        if (scwin.contnId != "input" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") != js_emp_no) {
            scwin.fn_filedown(dts_fileList.getCellData(scwin.rowPosition, "ATTACH_SEQ"));
        } else if (scwin.contnId == "input") {
            $c.win.alert("저장/수정 후 적용됩니다.");
        } else if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") == js_emp_no) {
            $c.win.alert("작성자는 파일클릭시 자동 다운로드 됩니다. \n\n입력된 비밀번호로 수정시, 저장/수정 후 적용됩니다.");
        }
    } else {
        if (filePw.getValue() != "") {
            if (scwin.contnId != "input" && dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") != js_emp_no) {
                $c.win.alert("비밀번호가 올바르지 않습니다.");
            } else if (scwin.contnId == "input") {
                $c.win.alert("저장을 해야 적용됩니다.");
            } else if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") == js_emp_no) {
                $c.win.alert("작성자는 파일클릭시 자동 다운로드 됩니다.");
            }
        } else {
            $c.win.alert("비밀번호를 입력해주세요");
        }
        filePw.focus();
    }
};
scwin.gform_onload = function() {
    scwin.fn_GetCode();
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(tbox_mkt_tp, false);
    $c.stf.showObj(filePw, false);
    $c.stf.showObj(label_16, false);
    $c.stf.showObj(btn_input, false);
    getContnId = $c.frame.path("../").fn_getContnId;
    scwin.contnId = getContnId();
    if (scwin.contnId != "input") {
        scwin.fn_read();
        //		showObj(panel_mail, false);
        cbox_mail_yn.setValue(0);
        scwin.iniPicYnSet();
        if (scwin.pwcnt > 0) {
            $c.stf.showObj(filePw, true);
            $c.stf.showObj(label_16, true);
            $c.stf.showObj(btn_input, true);
        }
        if (dts_ShareRoomInfo.getCellData(0, "WRTR_EMP_NO") == js_emp_no) {
            scwin.loadset = 1;
            scwin.iniAtachfFilePwSet();
        }
    } else {
        // 입력 화면 생성
        scwin.fn_setDataHeader();
        scwin.fn_SetSaveHeader();
        tbox_wrtr_emp_nm.setValue(js_emp_nm);
        tbox_reg_dep_nm.setValue(js_dep_nm);
        tbox_wrt_ddtm.setValue($c.ut.cGetToday("yyyy-mm-dd hh:mm:ss"));
        tbox_inq_cnt.setValue("0");
        tbox_mkt_tp.setValue(js_market);
        $c.stf.setObjectValue(rdo_creatloc_tp, '01');
        $c.stf.setObjectValue(cmb_secu_lvl_tp, '04');
        $c.stf.setObjectValue(rdo_creatloc_tp, '01');
        scwin.setChkValue(chb_impt_contn_yn, false);
        dts_KnowlgTp.UseFilter = true;
        dts_KnowlgTp.Filter();
        $c.stf.showObj(panel_mail, true);
    }
};
